#include <algorithm>
#include <iostream>
#include <string>
#include <vector>
struct Student { int id; std::string name; int mark; };
int main() {
    const std::vector<Student> students{{1, "Asha", 91}, {2, "Dev", 78}};
    const auto it = std::find_if(students.begin(), students.end(), [](const Student& s) { return s.id == 2; });
    if (it != students.end()) std::cout << it->name << ':' << it->mark << '\n';
}
